CREATE TABLE IF NOT EXISTS mentoria_recovery.respostas_usuarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES mentoria_auth.users(id), questao_id uuid NOT NULL REFERENCES mentoria_recovery.questoes(id), alternativa_id uuid NOT NULL REFERENCES mentoria_recovery.alternativas(id), correta boolean NOT NULL, tempo_resposta_segundos integer NOT NULL DEFAULT 0, questao_versao integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_mentoria_respostas_user_created ON mentoria_recovery.respostas_usuarios(usuario_id,created_at DESC);
